package com.example.data.local

import com.example.data.model.JobListing

object SeedDataProvider {

    fun extractSkills(role: String, notes: String): List<String> {
        val detected = mutableListOf<String>()
        val combined = "$role $notes".lowercase()

        val skillMap = listOf(
            "Java" to listOf("java"),
            "Spring Boot" to listOf("spring", "spring boot"),
            "Kotlin" to listOf("kotlin"),
            "Python" to listOf("python"),
            "Go" to listOf("golang", "go developer", "java/go"),
            "Microservices" to listOf("microservice", "microservices"),
            "PostgreSQL" to listOf("postgresql", "postgres"),
            "Redis" to listOf("redis"),
            "Kafka" to listOf("kafka"),
            "RabbitMQ" to listOf("rabbitmq"),
            "REST APIs" to listOf("rest", "api", "apis"),
            "Distributed Systems" to listOf("distributed", "distributed systems", "concurrency"),
            "WebSockets" to listOf("websocket", "websockets"),
            "Docker" to listOf("docker", "containers"),
            "AWS" to listOf("aws", "cloud"),
            "AI / LLM" to listOf("ai", "agent", "llm", "vector", "inference"),
            "IoT / Telematics" to listOf("iot", "telemetry", "telematics", "ocpp"),
            "Fintech / Ledgers" to listOf("ledger", "banking", "payments", "lending")
        )

        for ((label, triggers) in skillMap) {
            if (triggers.any { combined.contains(it) }) {
                detected.add(label)
            }
        }

        if (detected.isEmpty()) {
            detected.addAll(listOf("Java", "Backend APIs", "PostgreSQL", "Microservices"))
        }

        return detected.take(5)
    }

    private fun inferSalary(funding: String, matchScore: String): String {
        return when {
            funding.contains("Unicorn") || funding.contains("Series D") || funding.contains("Series E") || funding.contains("Series F") -> "₹35L - ₹60L + ESOPs"
            funding.contains("Series B") || funding.contains("Series C") -> "₹28L - ₹48L + ESOPs"
            funding.contains("Series A") -> "₹24L - ₹40L + Equity"
            funding.contains("Seed") || funding.contains("Pre-Seed") -> "₹20L - ₹36L + Generous Equity"
            else -> "₹25L - ₹45L Competitive"
        }
    }

    val initialJobs: List<JobListing> by lazy {
        rawCsvData.lines()
            .drop(1) // Header
            .filter { it.isNotBlank() }
            .mapIndexed { index, line ->
                val tokens = parseCsvLine(line)
                val date = tokens.getOrElse(0) { "2026-10-01" }
                val company = tokens.getOrElse(1) { "Tech Startup" }
                val funding = tokens.getOrElse(2) { "Venture Funded" }
                val location = tokens.getOrElse(3) { "Bangalore / Remote" }
                val role = tokens.getOrElse(4) { "Backend Engineer" }
                val matchScore = tokens.getOrElse(5) { "9/10" }
                val applyLink = tokens.getOrElse(6) { "https://careers.google.com" }
                val outreach = tokens.getOrElse(7) { "No" }
                val response = tokens.getOrElse(8) { "No" }
                val notes = tokens.getOrElse(9) { "Actively hiring for core backend systems." }

                val skills = extractSkills(role, notes)
                val salary = inferSalary(funding, matchScore)

                JobListing(
                    id = "job_${index + 1}",
                    companyName = company,
                    roleTitle = role,
                    location = location,
                    salaryRange = salary,
                    skills = skills,
                    descriptionSnippet = notes,
                    sourceUrl = applyLink,
                    status = JobListing.STATUS_PENDING,
                    fundingStage = funding,
                    matchScore = matchScore,
                    notes = notes,
                    dateAdded = date,
                    outreachSent = outreach,
                    response = response
                )
            }
    }

    private fun parseCsvLine(line: String): List<String> {
        val result = mutableListOf<String>()
        val sb = StringBuilder()
        var inQuotes = false

        for (ch in line) {
            when {
                ch == '\"' -> inQuotes = !inQuotes
                ch == ',' && !inQuotes -> {
                    result.add(sb.toString().trim())
                    sb.clear()
                }
                else -> sb.append(ch)
            }
        }
        result.add(sb.toString().trim())
        return result
    }

